import{_ as t,c as e,o,a3 as r}from"./chunks/framework.p1dVAvtz.js";const g=JSON.parse('{"title":"Detalle de Mantenimiento de Cubiertas","description":"","frontmatter":{},"headers":[],"relativePath":"flows/Mantenimiento/DetalledeMantenimientodeCubiertas.md","filePath":"flows/Mantenimiento/DetalledeMantenimientodeCubiertas.md","lastUpdated":1759236618000}'),n={name:"flows/Mantenimiento/DetalledeMantenimientodeCubiertas.md"};function i(d,a,s,l,c,u){return o(),e("div",null,a[0]||(a[0]=[r('<h1 id="detalle-de-mantenimiento-de-cubiertas" tabindex="-1">Detalle de Mantenimiento de Cubiertas <a class="header-anchor" href="#detalle-de-mantenimiento-de-cubiertas" aria-label="Permalink to &quot;Detalle de Mantenimiento de Cubiertas&quot;">​</a></h1><h2 id="registro-de-actividades-montaje-desmontaje-rotacion" tabindex="-1">Registro de Actividades (Montaje, Desmontaje, Rotación) <a class="header-anchor" href="#registro-de-actividades-montaje-desmontaje-rotacion" aria-label="Permalink to &quot;Registro de Actividades (Montaje, Desmontaje, Rotación)&quot;">​</a></h2><p>Esta documentación aplica después de generar la cabecera de la Orden de Trabajo (<strong>MAN Mantenimiento de unidades</strong>). Este paso detalla la acción específica realizada sobre una o más cubiertas.</p><h3 id="pantalla-base-man-mantenimiento-de-unidades-→-mantenimiento-de-cubiertas" tabindex="-1">Pantalla Base: MAN Mantenimiento de unidades <strong>→</strong> Mantenimiento de cubiertas <a class="header-anchor" href="#pantalla-base-man-mantenimiento-de-unidades-→-mantenimiento-de-cubiertas" aria-label="Permalink to &quot;Pantalla Base: MAN Mantenimiento de unidades **→** Mantenimiento de cubiertas&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Campo</th><th>Propósito</th><th>Notas de Uso para Cubiertas</th></tr></thead><tbody><tr><td>Unidad</td><td>Vehículo seleccionado para la OT (se carga automáticamente desde la cabecera).</td><td>Ya estaria cargado desde antes.</td></tr><tr><td>Importante: Es la unidad donde se realiza la acción</td><td></td><td></td></tr><tr><td>Km</td><td>Kilometraje (Odómetro) de la unidad al momento de la intervención.</td><td>Dato CRÍTICO. Registrar este valor es esencial para el cálculo del Costo por Kilómetro (CPK) y el rendimiento de la cubierta.</td></tr><tr><td>Detalle</td><td>Listado de todas las actividades (cubiertas) que se van a realizar en esta OT.</td><td>Usar el botón &quot;AGREGAR&quot; para iniciar el registro de la actividad.</td></tr></tbody></table><h3 id="formulario-agregar-actividad-montaje-desmontaje-y-rotacion" tabindex="-1">Formulario &quot;Agregar actividad&quot;: Montaje, Desmontaje y Rotación <a class="header-anchor" href="#formulario-agregar-actividad-montaje-desmontaje-y-rotacion" aria-label="Permalink to &quot;Formulario &quot;Agregar actividad&quot;: Montaje, Desmontaje y Rotación&quot;">​</a></h3><p>Este formulario es el corazón del registro de las acciones. Se debe completar uno por cada movimiento de cubierta.</p><table tabindex="0"><thead><tr><th>Campo</th><th>Descripción y Uso</th><th>Procedimiento de Carga</th></tr></thead><tbody><tr><td>Cubierta</td><td>Código de Activo Interno (o Número de Serie)</td><td></td></tr><tr><td>Si no existe ver como ingresarlo</td><td>Ingresar mínimo 2 caracteres para filtrar y seleccionar la cubierta específica</td><td></td></tr><tr><td>Cantidad</td><td>Siempre debe ser 1,00 para mantener la trazabilidad unitaria.</td><td>Valor por defecto (no modificar).</td></tr><tr><td>Camión a Colocar</td><td>Vehículo (Unidad) o Depósito donde quedará la cubierta después de la acción.</td><td>Se debe seleccionar la Unidad de Destino o el Depósito si se desmonta para almacén/reparación.</td></tr><tr><td>PO</td><td>Posición de la cubierta en el vehículo o depósito.</td><td>Ingresar el Número de Posición según el estándar de la flota.</td></tr><tr><td>Estado</td><td>Estado final de la cubierta al registrar la actividad.</td><td>Ej: Nueva, Recapada, Vulcanizada, etc..</td></tr><tr><td>A COLOCAR</td><td>Indica una acción de INGRESO al Camión/Depósito seleccionado.</td><td>Marcar si la cubierta se monta o ingresa a un depósito/posición.</td></tr><tr><td>SALE</td><td>Indica una acción de SALIDA del Camión/Depósito seleccionado.</td><td>Marcar si la cubierta se desmonta o sale de una posición/depósito.</td></tr></tbody></table><h3 id="casos-de-uso-del-formulario" tabindex="-1">Casos de Uso del Formulario <a class="header-anchor" href="#casos-de-uso-del-formulario" aria-label="Permalink to &quot;Casos de Uso del Formulario&quot;">​</a></h3><p>El registro de la actividad depende de la acción que se esté realizando:</p><h4 id="_1-montaje-colocacion-en-un-vehiculo" tabindex="-1">1. Montaje (Colocación en un vehículo) <a class="header-anchor" href="#_1-montaje-colocacion-en-un-vehiculo" aria-label="Permalink to &quot;1. Montaje (Colocación en un vehículo)&quot;">​</a></h4><h5 id="objetivo-la-cubierta-pasa-de-almacen-deposito-a-unidad" tabindex="-1"><strong>Objetivo:</strong> La cubierta pasa de <strong>Almacén/Depósito</strong> a <strong>Unidad</strong> <a class="header-anchor" href="#objetivo-la-cubierta-pasa-de-almacen-deposito-a-unidad" aria-label="Permalink to &quot;**Objetivo:** La cubierta pasa de **Almacén/Depósito** a **Unidad**&quot;">​</a></h5><table tabindex="0"><thead><tr><th><strong>Acciones en el Formulario:</strong></th></tr></thead><tbody><tr><td>Marcar solo <strong>A COLOCAR</strong>.</td></tr><tr><td><strong>Cubierta:</strong> Código de Activo de la cubierta que se va a montar.</td></tr><tr><td><strong>Camión que sale:</strong> seria del depósito de Cubiertas</td></tr><tr><td><strong>Camión a Colocar:</strong> La <strong>Unidad</strong> donde se monta</td></tr><tr><td><strong>PO:</strong> Número de posición del eje donde se monta</td></tr><tr><td><strong>Estado:</strong> Se recomienda <strong>En Uso</strong></td></tr><tr><td><strong>Resultado:</strong> La Hoja de Vida de la cubierta se asocia a la nueva unidad/posición</td></tr></tbody></table><h4 id="_2-desmontaje-retiro-de-un-vehiculo" tabindex="-1">2. Desmontaje (Retiro de un vehículo) <a class="header-anchor" href="#_2-desmontaje-retiro-de-un-vehiculo" aria-label="Permalink to &quot;2. Desmontaje (Retiro de un vehículo)&quot;">​</a></h4><h5 id="objetivo-la-cubierta-pasa-de-una-unidad-a-almacen-reparacion-baja" tabindex="-1"><strong>Objetivo:</strong> La cubierta pasa de una <strong>Unidad</strong> a <strong>Almacén/Reparación/Baja</strong> <a class="header-anchor" href="#objetivo-la-cubierta-pasa-de-una-unidad-a-almacen-reparacion-baja" aria-label="Permalink to &quot;**Objetivo:** La cubierta pasa de una **Unidad** a **Almacén/Reparación/Baja**&quot;">​</a></h5><table tabindex="0"><thead><tr><th><strong>Acciones en el Formulario:</strong></th></tr></thead><tbody><tr><td>Marcar solo <strong>SALE</strong></td></tr><tr><td><strong>Cubierta:</strong> Código de Activo de la cubierta que se desmonta</td></tr><tr><td><strong>Camión que sale:</strong> La <strong>Unidad</strong> donde estaba montada</td></tr><tr><td><strong>Camión a Colocar:</strong> El <strong>Depósito</strong> o la <strong>Ubicación Temporal</strong> (Ej: Cubiertas)</td></tr><tr><td><strong>PO:</strong> Dónde estaba</td></tr><tr><td><strong>Estado:</strong> <strong>En Depósito</strong>, <strong>En Reparación</strong> o <strong>Baja</strong> (según el destino)</td></tr><tr><td><strong>Resultado:</strong> Se registra el kilometraje de salida de la cubierta y se actualiza su ubicación</td></tr></tbody></table><h4 id="_3-reparacion" tabindex="-1">3. Reparación <a class="header-anchor" href="#_3-reparacion" aria-label="Permalink to &quot;3. Reparación&quot;">​</a></h4><h5 id="objetivo-colocar-lo-que-se-realizo" tabindex="-1"><strong>Objetivo:</strong> Colocar lo que se realizó <a class="header-anchor" href="#objetivo-colocar-lo-que-se-realizo" aria-label="Permalink to &quot;**Objetivo:** Colocar lo que se realizó&quot;">​</a></h5><table tabindex="0"><thead><tr><th><strong>Procedimiento</strong></th></tr></thead><tbody><tr><td><strong>Cubierta:</strong> Código de Activo de la cubierta que se desmonta.</td></tr><tr><td><strong>Estado:</strong> <strong>Recapada, En Reparación</strong> o <strong>Baja</strong> (según el destino).</td></tr><tr><td><strong>Resultado:</strong> Se actualiza el estado del cubierta.</td></tr></tbody></table><h3 id="funcionalidad-adicional-cambio-de-ubicacion-el-lapiz" tabindex="-1">Funcionalidad Adicional: Cambio de Ubicación (El Lápiz) <a class="header-anchor" href="#funcionalidad-adicional-cambio-de-ubicacion-el-lapiz" aria-label="Permalink to &quot;Funcionalidad Adicional: Cambio de Ubicación (El Lápiz)&quot;">​</a></h3><ul><li><p><strong>Uso:</strong> Si la <strong>Unidad de Destino</strong> (<strong>Camión a Colocar</strong>) no existe o si se está moviendo la cubierta a un <strong>nuevo depósito/ubicación temporal</strong> que aún no está registrado.</p></li><li><p><strong>Procedimiento:</strong> Hacer clic en el icono del <strong>Lápiz</strong> (+ <strong>Lupa</strong> <strong>→ Lápiz</strong>) ubicado junto al campo <strong>Camión a Colocar</strong>. Esto abrirá un menú para <strong>crear una nueva Unidad (o Depósito)</strong> y luego seleccionarla como destino.</p></li></ul><h3 id="finalizacion" tabindex="-1">Finalización <a class="header-anchor" href="#finalizacion" aria-label="Permalink to &quot;Finalización&quot;">​</a></h3><ol><li><p>Hacer clic en <strong>&quot;GUARDAR&quot;</strong> en el formulario <strong>&quot;Agregar actividad&quot;</strong>. La actividad se lista en el <strong>detalle</strong> de la OT.</p></li><li><p>Repetir el proceso si hay más cubiertas involucradas.</p></li><li><p>Una vez cargadas todas las actividades, hacer clic en <strong>&quot;SIGUIENTE&quot;</strong> para finalizar la carga de los datos.</p></li></ol>',23)]))}const b=t(n,[["render",i]]);export{g as __pageData,b as default};
